import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"NestJS API 索引","description":"速查本手册 AI 服务子集实际讲过的 NestJS / Agent API 入口、关键点与正文链接，不是 Nest 全书。","frontmatter":{"title":"NestJS API 索引","description":"速查本手册 AI 服务子集实际讲过的 NestJS / Agent API 入口、关键点与正文链接，不是 Nest 全书。","outline":[2,3],"article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"ts-ai/appendix/api-index/nestjs-api-index.md","filePath":"ts-ai/appendix/api-index/nestjs-api-index.md","lastUpdated":1786166505000}'),c={name:"ts-ai/appendix/api-index/nestjs-api-index.md"};function r(n,e,s,i,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="nestjs-api-索引" tabindex="-1">NestJS API 索引 <a class="header-anchor" href="#nestjs-api-索引" aria-label="Permalink to &quot;NestJS API 索引&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本索引帮助你从装饰器、服务名或路由跳回 <code>docs/ts-ai/backend</code> 正文。条目只收录<strong>本手册 AI 服务子集</strong>（Agent API、Model Gateway、SSE、Thread/Run、上传与任务），不是 NestJS 框架百科。</p><h2 id="_1-索引范围与排除" tabindex="-1">1. 索引范围与排除 <a class="header-anchor" href="#_1-索引范围与排除" aria-label="Permalink to &quot;1. 索引范围与排除&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包含</th><th>排除</th></tr></thead><tbody><tr><td><code>@nestjs/common</code> / <code>core</code> / <code>config</code> / <code>swagger</code> / <code>bullmq</code> / <code>platform-express</code> 中本手册讲过的入口</td><td>未出现的 Nest 全家桶（微服务、GraphQL、CQRS、完整 Passport 策略等）</td></tr><tr><td>Module/DI、Controller/DTO/Pipe、Guard/Interceptor/Filter、Model Gateway、Agent Module、REST/SSE/上传、Thread·Run·数据与任务</td><td>纯前端协议实现（见 <a href="/ts-ai/appendix/api-index/vue-nuxt-ai-api-index">Vue 与 Nuxt AI API 索引</a>）</td></tr><tr><td>产品错误码、SSE 事件名、与 AI 服务相关的环境变量</td><td>LangChain/LangGraph 完整 API（见对应附录索引）</td></tr></tbody></table><p>查 API 时：先看「包与入口」，再进对应家族；机制与边界跟链接进正文。篇间命名有变体（如 <code>ModelGateway</code> / <code>ModelGatewayService</code>、<code>CreateRunDto</code> 字段差异）时，以链接正文为准。</p><h2 id="_2-包与入口对象" tabindex="-1">2. 包与入口对象 <a class="header-anchor" href="#_2-包与入口对象" aria-label="Permalink to &quot;2. 包与入口对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包 / 入口</th><th>本手册常用对象</th><th>正文</th></tr></thead><tbody><tr><td><code>@nestjs/common</code></td><td><code>@Module</code>、<code>@Injectable</code>、<code>@Controller</code>、<code>@Get</code>/<code>@Post</code>、<code>ValidationPipe</code>、HTTP 异常、<code>Scope</code></td><td><a href="/ts-ai/backend/nestjs-core/modules-providers-dependency-injection">模块与 DI</a>、<a href="/ts-ai/backend/nestjs-core/controllers-pipes-dto">Controller / DTO / Pipe</a></td></tr><tr><td><code>@nestjs/core</code></td><td><code>NestFactory.create</code>、<code>APP_INTERCEPTOR</code></td><td><a href="/ts-ai/backend/nestjs-core/project-structure-bootstrap">项目结构与启动</a></td></tr><tr><td><code>@nestjs/config</code></td><td><code>ConfigModule.forRoot</code>、<code>ConfigService</code></td><td>同上；密钥注入见 <a href="/ts-ai/backend/ai-service/nestjs-langchain-integration">Nest 集成 LangChain</a></td></tr><tr><td><code>@nestjs/swagger</code></td><td><code>DocumentBuilder</code>、<code>SwaggerModule</code>、<code>@ApiProperty</code> 等</td><td><a href="/ts-ai/backend/api-realtime/openapi-contracts">OpenAPI 契约</a></td></tr><tr><td><code>@nestjs/platform-express</code></td><td><code>FileInterceptor</code>、Multer</td><td><a href="/ts-ai/backend/api-realtime/file-upload">文件上传</a></td></tr><tr><td><code>@nestjs/bullmq</code> / <code>bullmq</code></td><td><code>@InjectQueue</code>、<code>@Processor</code>、<code>WorkerHost</code>、<code>Queue</code>/<code>Worker</code>/<code>Job</code></td><td><a href="/ts-ai/backend/data-tasks/bullmq-reliable-workers">BullMQ 可靠 Worker</a></td></tr><tr><td><code>class-validator</code> / <code>class-transformer</code></td><td><code>@IsString</code>、<code>@ValidateNested</code>、<code>@Type</code></td><td><a href="/ts-ai/backend/nestjs-core/controllers-pipes-dto">Controller / DTO / Pipe</a></td></tr><tr><td><code>langchain</code> / <code>@langchain/openai</code> / <code>zod</code></td><td><code>createAgent</code>、<code>tool</code>、<code>ChatOpenAI</code>、<code>contextSchema</code></td><td><a href="/ts-ai/backend/ai-service/agent-module-tool-registry">Agent Module</a>、<a href="/ts-ai/backend/ai-service/model-gateway">Model Gateway</a></td></tr><tr><td>应用入口</td><td><code>main.ts</code> → <code>bootstrap()</code> → <code>AppModule</code>；<code>setGlobalPrefix(&#39;v1&#39;)</code>；全局 Pipe/Filter；<code>enableShutdownHooks</code></td><td><a href="/ts-ai/backend/nestjs-core/project-structure-bootstrap">启动</a>、<a href="/ts-ai/backend/nestjs-core/minimal-agent-api-skeleton">最小 Agent API</a></td></tr><tr><td>Worker / WS 入口</td><td>独立 <code>worker/main</code>；WS namespace <code>/agent</code></td><td><a href="/ts-ai/backend/data-tasks/bullmq-reliable-workers">BullMQ</a>、<a href="/ts-ai/backend/api-realtime/websocket-sessions">WebSocket 会话</a></td></tr></tbody></table><p>根模块常见聚合：<code>ConfigModule</code> + <code>LangChainModule</code> / Gateway + <code>AgentModule</code> + <code>RunsModule</code> +（可选）<code>PrismaModule</code> / Redis / BullMQ。</p><h2 id="_3-核心-api-家族" tabindex="-1">3. 核心 API 家族 <a class="header-anchor" href="#_3-核心-api-家族" aria-label="Permalink to &quot;3. 核心 API 家族&quot;">​</a></h2><h3 id="_3-1-module-provider-di" tabindex="-1">3.1 Module / Provider / DI <a class="header-anchor" href="#_3-1-module-provider-di" aria-label="Permalink to &quot;3.1 Module / Provider / DI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>关键点</th><th>正文</th></tr></thead><tbody><tr><td><code>@Module({ imports, controllers, providers, exports })</code></td><td>声明编译边界与对外导出</td><td>只能拿到对方 <code>exports</code>；<code>exports</code> 须来自本模块 providers 或 re-export</td><td><a href="/ts-ai/backend/nestjs-core/modules-providers-dependency-injection">模块与 DI</a></td></tr><tr><td><code>@Injectable()</code> / <code>@Injectable({ scope })</code></td><td>可注入 Provider</td><td><code>Scope.DEFAULT</code> 适合 Gateway/Agent 工厂；<code>REQUEST</code> 适合租户 Context（会污染上层单例）</td><td><a href="/ts-ai/backend/nestjs-core/scopes-lifecycle">作用域与生命周期</a></td></tr><tr><td><code>@Inject(token)</code> / <code>provide</code> + <code>useExisting</code> / <code>useFactory</code> / <code>useValue</code></td><td>Token 注入与工厂注册</td><td>例：<code>MODEL_GATEWAY</code>；密钥只经 <code>ConfigService</code> 进 Registry</td><td><a href="/ts-ai/backend/nestjs-core/modules-providers-dependency-injection">模块与 DI</a>、<a href="/ts-ai/backend/ai-service/nestjs-langchain-integration">Nest↔LangChain</a></td></tr><tr><td><code>LangChainModule.forRootAsync()</code> / <code>DynamicModule</code></td><td>异步注册 ModelRegistry + Gateway</td><td>常 <code>global: true</code>；<code>getOrThrow(&#39;OPENAI_API_KEY&#39;)</code></td><td><a href="/ts-ai/backend/ai-service/nestjs-langchain-integration">Nest↔LangChain</a></td></tr><tr><td><code>AgentModule</code> / <code>RunsModule</code> / <code>PrismaModule</code> / <code>RedisModule</code></td><td>领域模块边界</td><td>Agent 导出工厂/服务；Runs 依赖 Agent；Prisma/Redis 可 <code>@Global</code></td><td><a href="/ts-ai/backend/nestjs-core/modules-providers-dependency-injection">模块与 DI</a>、<a href="/ts-ai/backend/data-tasks/postgresql-orm-migrations">Prisma</a>、<a href="/ts-ai/backend/data-tasks/redis-state-ownership">Redis 归属</a></td></tr><tr><td><code>OnModuleInit</code> / <code>OnModuleDestroy</code> / <code>beforeApplicationShutdown</code></td><td>连接、校验与优雅停机</td><td>Prisma <code>$connect</code>/<code>$disconnect</code>；SIGTERM 停接新 Run</td><td><a href="/ts-ai/backend/nestjs-core/scopes-lifecycle">作用域与生命周期</a></td></tr><tr><td><code>forwardRef</code></td><td>打破循环依赖（慎用）</td><td>优先抽第三模块，避免 <code>agent</code>↔<code>runs</code> 双向 import</td><td><a href="/ts-ai/backend/nestjs-core/modules-providers-dependency-injection">模块与 DI</a></td></tr><tr><td><code>Test.createTestingModule</code> / <code>overrideProvider</code></td><td>测试替换 Gateway</td><td>mock <code>resolve()</code>，不打真模型</td><td><a href="/ts-ai/backend/ai-service/nestjs-langchain-integration">Nest↔LangChain</a>、<a href="/ts-ai/backend/ai-service/model-gateway">Model Gateway</a></td></tr></tbody></table><p>领域服务速查：<code>AgentService</code>、<code>AgentFactoryService</code>、<code>ModelGateway(Service)</code>、<code>ModelRegistry</code>、<code>ToolRegistryService</code>、<code>PromptConfigService</code>、<code>RequestContext</code> / <code>RequestContextService</code>、<code>RunsService</code>、<code>RunStreamService</code>、<code>FileUploadService</code>、<code>PrismaService</code>。</p><h3 id="_3-2-controller-dto-pipe" tabindex="-1">3.2 Controller / DTO / Pipe <a class="header-anchor" href="#_3-2-controller-dto-pipe" aria-label="Permalink to &quot;3.2 Controller / DTO / Pipe&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>关键点</th><th>正文</th></tr></thead><tbody><tr><td><code>@Controller</code> + <code>@Get</code> / <code>@Post</code> / <code>@Param</code> / <code>@Body</code> / <code>@Headers</code></td><td>HTTP 路由与参数绑定</td><td><strong>手册默认</strong>：<code>setGlobalPrefix(&#39;v1&#39;)</code> + 短路径（如 <code>@Controller(&#39;runs&#39;)</code>）；勿在 Controller 再写 <code>v1/…</code></td><td><a href="/ts-ai/backend/nestjs-core/controllers-pipes-dto">Controller / DTO / Pipe</a>、<a href="/ts-ai/backend/api-realtime/rest-agent-api">REST Agent API</a></td></tr><tr><td><code>ValidationPipe</code></td><td>DTO 白名单与转型</td><td><code>whitelist</code>、<code>forbidNonWhitelisted</code>、<code>transform: true</code>；失败 → <code>BadRequestException</code> / <code>VALIDATION_*</code></td><td>同上；<a href="/ts-ai/backend/nestjs-core/project-structure-bootstrap">启动</a></td></tr><tr><td><code>CreateRunDto</code> / <code>RunMessageDto</code> / <code>CreateThreadDto</code> / <code>CancelRunDto</code></td><td>Run/Thread 入参契约</td><td>字段变体：<code>input</code>（入门）/<code>message</code>（最小骨架）/<code>messages[]</code>（REST）；拒客户端伪造 <code>assistant</code>/<code>tool</code></td><td><a href="/ts-ai/backend/nestjs-core/controllers-pipes-dto">Controller</a>、<a href="/ts-ai/backend/nestjs-core/minimal-agent-api-skeleton">最小骨架</a>、<a href="/ts-ai/backend/api-realtime/rest-agent-api">REST</a></td></tr><tr><td><code>RunResponseDto</code> / <code>ApiErrorDto</code> / <code>FileResponseDto</code></td><td>稳定响应与错误体</td><td><code>runId</code>/<code>status</code>/<code>output?</code>；错误含 <code>code</code>/<code>message</code>/<code>requestId</code></td><td><a href="/ts-ai/backend/api-realtime/rest-agent-api">REST</a>、<a href="/ts-ai/backend/api-realtime/openapi-contracts">OpenAPI</a>、<a href="/ts-ai/backend/api-realtime/file-upload">上传</a></td></tr><tr><td><code>@HttpCode(HttpStatus.ACCEPTED)</code></td><td>异步创建 Run</td><td>常见 202 + <code>runId</code>；Thread 创建常用 201</td><td><a href="/ts-ai/backend/api-realtime/rest-agent-api">REST Agent API</a></td></tr><tr><td><code>@Sse</code> / <code>@Res</code> / <code>@UploadedFile</code></td><td>SSE、手写流、multipart</td><td><code>@Sse</code> 返回 <code>Observable&lt;MessageEvent&gt;</code>；上传用 <code>FileInterceptor(&#39;file&#39;)</code></td><td><a href="/ts-ai/backend/api-realtime/sse-streaming">SSE</a>、<a href="/ts-ai/backend/api-realtime/file-upload">上传</a></td></tr></tbody></table><p>控制器速查：<code>ThreadsController</code>、<code>RunsController</code>、<code>RunStreamController</code>、<code>FilesController</code>。</p><h3 id="_3-3-guard-interceptor-filter" tabindex="-1">3.3 Guard / Interceptor / Filter <a class="header-anchor" href="#_3-3-guard-interceptor-filter" aria-label="Permalink to &quot;3.3 Guard / Interceptor / Filter&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>关键点</th><th>正文</th></tr></thead><tbody><tr><td><code>CanActivate</code> / <code>@UseGuards</code></td><td>鉴权与配额闸门</td><td><code>true</code> 放行；<code>UnauthorizedException</code>→401；<code>false</code>→403</td><td><a href="/ts-ai/backend/nestjs-core/guards-interceptors-filters">Guard / Interceptor / Filter</a></td></tr><tr><td><code>DevAuthGuard</code> / <code>AuthGuard</code> / <code>JwtAuthGuard</code> / <code>RunQuotaGuard</code></td><td>开发 Token / Bearer / 配额</td><td>生产禁用 Dev；SSE/上传与 REST 共用鉴权假设</td><td>同上；<a href="/ts-ai/backend/api-realtime/rest-agent-api">REST</a>、<a href="/ts-ai/backend/api-realtime/sse-streaming">SSE</a></td></tr><tr><td><code>NestInterceptor</code> / <code>LoggingInterceptor</code> / <code>BindRequestContextInterceptor</code></td><td>追踪、耗时、填充 REQUEST Context</td><td>管道顺序：Middleware → Guard → Interceptor 前 → Pipe → Handler → Interceptor 后</td><td><a href="/ts-ai/backend/nestjs-core/guards-interceptors-filters">Guard 篇</a>、<a href="/ts-ai/backend/nestjs-core/scopes-lifecycle">作用域</a></td></tr><tr><td><code>ExceptionFilter</code> / <code>AiExceptionFilter</code> / <code>@Catch()</code></td><td>统一 AI/HTTP 错误 JSON</td><td>优先读 <code>HttpException</code> body.<code>code</code>；附 <code>traceId</code>/<code>path</code>/<code>timestamp</code></td><td><a href="/ts-ai/backend/nestjs-core/guards-interceptors-filters">Guard 篇</a></td></tr><tr><td><code>RequestContextMiddleware</code> / ALS / <code>@Inject(REQUEST)</code></td><td>租户与请求上下文</td><td>Worker 必须显式 <code>ctx.run</code>；REQUEST-scope 会改变上层作用域</td><td><a href="/ts-ai/backend/ai-service/request-context-tenancy">请求上下文与多租户</a></td></tr><tr><td><code>UnauthorizedException</code> / <code>BadRequestException</code> / <code>NotFoundException</code> / <code>ConflictException</code></td><td>标准 HTTP 异常</td><td>映射到产品错误码（见 §4）</td><td><a href="/ts-ai/backend/nestjs-core/guards-interceptors-filters">Guard</a>、<a href="/ts-ai/backend/api-realtime/rest-agent-api">REST</a>、<a href="/ts-ai/backend/data-tasks/long-tasks-idempotency-recovery">长任务</a></td></tr></tbody></table><h3 id="_3-4-model-gateway-与-agent-module" tabindex="-1">3.4 Model Gateway 与 Agent Module <a class="header-anchor" href="#_3-4-model-gateway-与-agent-module" aria-label="Permalink to &quot;3.4 Model Gateway 与 Agent Module&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>关键点</th><th>正文</th></tr></thead><tbody><tr><td><code>ModelGateway</code> / <code>ModelGatewayService</code></td><td>统一模型入口</td><td><code>resolve(alias?)</code>、<code>listAliases()</code>；未知别名 → <code>NotFoundException</code></td><td><a href="/ts-ai/backend/ai-service/model-gateway">Model Gateway</a></td></tr><tr><td><code>ModelRegistry</code> / <code>RegistryOptions</code></td><td>别名→<code>ChatOpenAI</code> 注册与缓存</td><td><code>openAiApiKey</code>、<code>baseURL?</code>、<code>defaultModel</code>、<code>timeoutMs</code>；建议 <code>maxRetries: 0</code></td><td>同上；<a href="/ts-ai/backend/ai-service/nestjs-langchain-integration">Nest↔LangChain</a></td></tr><tr><td><code>withFallbacks</code></td><td>主备 Runnable</td><td>可预包装进 Gateway；流式通常只在建流失败时回退</td><td><a href="/ts-ai/backend/ai-service/model-gateway">Model Gateway</a></td></tr><tr><td><code>AgentFactoryService</code></td><td>唯一 <code>createAgent</code> 组装入口</td><td><code>createSupportAgent()</code> / <code>create(agentKey)</code>；<strong>勿</strong> REQUEST-scope Agent</td><td><a href="/ts-ai/backend/ai-service/agent-module-tool-registry">Agent Module</a>、<a href="/ts-ai/backend/ai-service/nestjs-langchain-integration">Nest↔LangChain</a></td></tr><tr><td><code>createAgent</code> / <code>agent.invoke</code> / <code>agent.stream</code> / <code>streamEvents</code></td><td>执行 Agent</td><td>第二参：<code>context</code>、<code>configurable.thread_id</code>、<code>signal</code>；SSE/WS 适配产品事件</td><td><a href="/ts-ai/backend/ai-service/agent-module-tool-registry">Agent Module</a>、<a href="/ts-ai/backend/api-realtime/sse-streaming">SSE</a></td></tr><tr><td><code>tool</code> / <code>ToolRegistryService</code></td><td>定义与按名解析工具</td><td>Schema 只放业务主键；身份从 <code>config.context</code>；<code>resolve(names)</code></td><td><a href="/ts-ai/backend/ai-service/agent-module-tool-registry">Agent Module</a></td></tr><tr><td><code>supportContextSchema</code> / <code>requestContextSchema</code></td><td>Zod 受信上下文</td><td><code>tenantId</code>/<code>userId</code>（可扩 <code>roles</code>/<code>requestId</code>）</td><td><a href="/ts-ai/backend/ai-service/agent-module-tool-registry">Agent Module</a>、<a href="/ts-ai/backend/ai-service/request-context-tenancy">请求上下文</a></td></tr><tr><td><code>PromptConfigService.getSystemPrompt</code></td><td>配置化 systemPrompt</td><td>env override → version → env 匹配 → 最高 version；缺记录抛错</td><td><a href="/ts-ai/backend/ai-service/prompt-configuration-management">Prompt 配置</a></td></tr></tbody></table><h3 id="_3-5-rest-sse-上传契约" tabindex="-1">3.5 REST / SSE / 上传契约 <a class="header-anchor" href="#_3-5-rest-sse-上传契约" aria-label="Permalink to &quot;3.5 REST / SSE / 上传契约&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API / 路由</th><th>用途</th><th>关键点</th><th>正文</th></tr></thead><tbody><tr><td><code>POST /v1/threads</code></td><td>创建 Thread</td><td>201；可选 <code>Idempotency-Key</code></td><td><a href="/ts-ai/backend/api-realtime/rest-agent-api">REST Agent API</a></td></tr><tr><td><code>POST /v1/threads/:threadId/runs</code>（及入门 <code>POST /runs</code>）</td><td>创建并执行 Run</td><td>同步完成 / 异步 202；头 <code>Idempotency-Key</code> → <code>(tenantId, key)</code> 唯一</td><td><a href="/ts-ai/backend/api-realtime/rest-agent-api">REST</a>、<a href="/ts-ai/backend/data-tasks/long-tasks-idempotency-recovery">幂等与恢复</a></td></tr><tr><td><code>GET /v1/runs/:runId</code></td><td>查 Run 终态</td><td>异步模式校对；前端重连后也可 REST 校对</td><td><a href="/ts-ai/backend/api-realtime/rest-agent-api">REST</a>、<a href="/ts-ai/backend/api-realtime/">API 总览</a></td></tr><tr><td><code>GET /v1/runs/:runId/stream</code> + <code>@Sse</code> / 手写 <code>text/event-stream</code></td><td>订阅产品 SSE</td><td>返回 <code>Observable</code> 或手写帧；断开 → <code>AbortController</code>；映射层勿暴露原始 LangGraph 事件名</td><td><a href="/ts-ai/backend/api-realtime/sse-streaming">SSE 流式</a></td></tr><tr><td><code>POST /runs/:id/cancel</code> 或 <code>DELETE /runs/:id</code></td><td>取消 Run</td><td>篇间路径变体；幂等至 <code>cancelled</code></td><td><a href="/ts-ai/backend/nestjs-core/controllers-pipes-dto">Controller</a>、<a href="/ts-ai/backend/data-tasks/thread-run-message-model">Thread·Run</a>、<a href="/ts-ai/backend/data-tasks/long-tasks-idempotency-recovery">长任务</a></td></tr><tr><td><code>POST /v1/files</code> / <code>GET /v1/files/:fileId</code></td><td>上传与索引状态</td><td>multipart；<code>FileInterceptor</code> 限大小；状态 <code>pending|processing|ready|failed</code></td><td><a href="/ts-ai/backend/api-realtime/file-upload">文件上传</a></td></tr><tr><td><code>DocumentBuilder</code> / <code>SwaggerModule</code> / <code>@Api*</code></td><td>OpenAPI 文档与契约测试</td><td>UI <code>/api/docs</code>；CI 可 <code>EXPORT_OPENAPI=1</code></td><td><a href="/ts-ai/backend/api-realtime/openapi-contracts">OpenAPI 契约</a></td></tr><tr><td><code>@WebSocketGateway</code> / <code>@SubscribeMessage</code></td><td>可选双向会话</td><td>namespace <code>/agent</code>；事件 <code>thread.join</code> / <code>run.start</code> / <code>run.cancel</code>；默认传输仍是 REST+SSE</td><td><a href="/ts-ai/backend/api-realtime/websocket-sessions">WebSocket 会话</a></td></tr></tbody></table><p>产品事件映射入口：<code>mapAgentSnapshotToProductEvents</code>（SSE/WS 共用语义）。</p><h3 id="_3-6-thread·run·数据与任务入口" tabindex="-1">3.6 Thread·Run·数据与任务入口 <a class="header-anchor" href="#_3-6-thread·run·数据与任务入口" aria-label="Permalink to &quot;3.6 Thread·Run·数据与任务入口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>关键点</th><th>正文</th></tr></thead><tbody><tr><td><code>Thread</code> / <code>Run</code> / <code>Message</code></td><td>会话域模型</td><td>Run 五态：<code>queued→running→(completed|failed|cancelled)</code>；终态不可逆</td><td><a href="/ts-ai/backend/data-tasks/thread-run-message-model">Thread·Run·Message</a></td></tr><tr><td><code>transitionRun</code> / <code>appendMessages</code> / <code>persistTrajectory</code></td><td>状态迁移与轨迹写入</td><td><code>updateMany</code> count≠1 → <code>ConflictException</code>；按 <code>sequence</code> 幂等 append</td><td>同上；<a href="/ts-ai/backend/data-tasks/postgresql-orm-migrations">Prisma</a></td></tr><tr><td><code>PrismaService</code> / <code>$transaction</code> / migrate</td><td>Postgres 真相源</td><td>幂等唯一：<code>@@unique([tenantId, idempotencyKey])</code>；生产 <code>migrate deploy</code></td><td><a href="/ts-ai/backend/data-tasks/postgresql-orm-migrations">PostgreSQL 与迁移</a></td></tr><tr><td><code>Queue.add</code> / <code>Worker</code> / <code>AgentRunJobData</code></td><td>Agent Run 与索引任务</td><td>Job 只带 id；payload 读库；<code>jobId: run.id</code>；DLQ 归档</td><td><a href="/ts-ai/backend/data-tasks/bullmq-reliable-workers">BullMQ</a>、<a href="/ts-ai/backend/api-realtime/file-upload">上传</a></td></tr><tr><td>Redis：<code>lock:thread:…</code> / <code>cancel:run:…</code> / <code>stream:run:…</code> / 限流键</td><td>互斥、取消标记、短缓冲、配额</td><td>key 含 <code>tenantId</code>；真相仍在 Postgres</td><td><a href="/ts-ai/backend/data-tasks/redis-state-ownership">Redis 归属</a></td></tr><tr><td><code>cancelRun</code> / 孤儿 Run Cron</td><td>三路取消与卡死清扫</td><td>DB→cancelled + Redis SET + 移除 waiting Job + Worker abort；超时 → <code>WORKER_TIMEOUT</code></td><td><a href="/ts-ai/backend/data-tasks/long-tasks-idempotency-recovery">长任务与幂等</a></td></tr></tbody></table><h2 id="_4-事件、错误与配置速查" tabindex="-1">4. 事件、错误与配置速查 <a class="header-anchor" href="#_4-事件、错误与配置速查" aria-label="Permalink to &quot;4. 事件、错误与配置速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>关键项</th><th>放哪里处理</th><th>正文</th></tr></thead><tbody><tr><td>产品 SSE 事件</td><td><code>run.started</code>、<code>message.delta</code>、<code>tool.started</code>/<code>completed</code>、<code>run.completed</code>/<code>failed</code>/<code>cancelled</code>、<code>ping</code></td><td><code>RunStreamService</code> / 映射层；勿直出框架内部事件名</td><td><a href="/ts-ai/backend/api-realtime/sse-streaming">SSE</a>、<a href="/ts-ai/backend/api-realtime/openapi-contracts">OpenAPI <code>SseEvent</code></a></td></tr><tr><td>WS 入站</td><td><code>thread.join</code>、<code>run.start</code>、<code>run.cancel</code></td><td><code>AgentWsGateway</code>；断线 abort</td><td><a href="/ts-ai/backend/api-realtime/websocket-sessions">WebSocket</a></td></tr><tr><td>鉴权/校验错误</td><td><code>UNAUTHORIZED</code>、<code>FORBIDDEN</code>、<code>VALIDATION_ERROR</code>/<code>FAILED</code>、<code>INVALID_REQUEST</code></td><td>Guard / ValidationPipe / Filter</td><td><a href="/ts-ai/backend/nestjs-core/guards-interceptors-filters">Guard</a>、<a href="/ts-ai/backend/api-realtime/rest-agent-api">REST</a></td></tr><tr><td>资源/冲突</td><td><code>THREAD_NOT_FOUND</code>、<code>RUN_NOT_FOUND</code>、<code>IDEMPOTENCY_CONFLICT</code></td><td>404 / 409</td><td><a href="/ts-ai/backend/api-realtime/rest-agent-api">REST</a>、<a href="/ts-ai/backend/data-tasks/long-tasks-idempotency-recovery">长任务</a></td></tr><tr><td>模型与限流</td><td><code>RATE_LIMITED</code>/<code>AI_RATE_LIMIT</code>、<code>MODEL_UNAVAILABLE</code>、<code>MODEL_UPSTREAM_ERROR</code>、<code>CONTEXT_TOO_LONG</code></td><td>Gateway / Filter / Redis 计数</td><td><a href="/ts-ai/backend/nestjs-core/guards-interceptors-filters">Guard</a>、<a href="/ts-ai/backend/ai-service/model-gateway">Gateway</a></td></tr><tr><td>流与上传</td><td><code>RUN_EXECUTION_ERROR</code>/<code>STREAM_ERROR</code>、<code>FILE_REQUIRED</code>、<code>MIME_NOT_ALLOWED</code>、<code>FILE_TOO_LARGE</code>、<code>PARSE_FAILED</code></td><td>SSE 帧或上传校验</td><td><a href="/ts-ai/backend/api-realtime/sse-streaming">SSE</a>、<a href="/ts-ai/backend/api-realtime/file-upload">上传</a></td></tr><tr><td>配置/密钥</td><td><code>OPENAI_API_KEY</code>、<code>OPENAI_BASE_URL</code>、<code>LLM_*</code>/<code>AGENT_DEFAULT_MODEL</code>、<code>DATABASE_URL</code>、<code>REDIS_URL</code>/<code>BULLMQ_REDIS_URL</code>、Prompt 覆盖变量</td><td>只经 <code>ConfigService</code>；启动 fail-fast</td><td><a href="/ts-ai/backend/nestjs-core/project-structure-bootstrap">启动</a>、<a href="/ts-ai/backend/ai-service/nestjs-langchain-integration">Nest↔LangChain</a>、<a href="/ts-ai/backend/ai-service/prompt-configuration-management">Prompt</a></td></tr><tr><td>请求头</td><td><code>Authorization</code>、<code>Idempotency-Key</code>、<code>x-trace-id</code>/<code>x-request-id</code></td><td>Guard / 幂等 / 日志关联</td><td><a href="/ts-ai/backend/api-realtime/rest-agent-api">REST</a>、<a href="/ts-ai/backend/ai-service/request-context-tenancy">请求上下文</a></td></tr></tbody></table><h2 id="_5-关联章节" tabindex="-1">5. 关联章节 <a class="header-anchor" href="#_5-关联章节" aria-label="Permalink to &quot;5. 关联章节&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>用本索引时怎么用</th></tr></thead><tbody><tr><td><a href="/ts-ai/backend/">服务端工程总览</a></td><td>建立 Nest Core → AI Service → API → Data/Tasks 学习顺序</td></tr><tr><td><a href="/ts-ai/backend/nestjs-core/">NestJS Core</a></td><td>Module/DI、Controller、Guard、最小骨架</td></tr><tr><td><a href="/ts-ai/backend/ai-service/">AI 服务架构</a></td><td>Gateway、Agent Module、Prompt、租户上下文</td></tr><tr><td><a href="/ts-ai/backend/api-realtime/">API 与实时通道</a></td><td>REST、SSE、上传、OpenAPI、可选 WS</td></tr><tr><td><a href="/ts-ai/backend/data-tasks/">数据与任务</a></td><td>Thread/Run、Prisma、Redis、BullMQ、幂等恢复</td></tr><tr><td><a href="/ts-ai/backend/assembly/assembly-recipes-checklist">AI 服务组装配方</a></td><td>按配方验收「会用哪些入口」</td></tr><tr><td><a href="/ts-ai/appendix/api-index/vue-nuxt-ai-api-index">Vue 与 Nuxt AI API 索引</a></td><td>前端如何消费本索引中的 REST/SSE</td></tr><tr><td><a href="/ts-ai/appendix/references/official-resources">官方资料索引</a></td><td>本索引未收录的 API，以官方文档为准</td></tr><tr><td><a href="/ts-ai/appendix/api-index/langchain-api-index">LangChain.js API 索引</a></td><td><code>createAgent</code> / <code>tool</code> / <code>ChatOpenAI</code> 细节</td></tr><tr><td><a href="/ts-ai/appendix/learning/knowledge-checklist">知识点清单</a></td><td>行为验收勾选，不代替本索引的 API 跳转</td></tr></tbody></table>',29)])])}const b=t(c,[["render",r]]);export{u as __pageData,b as default};
